def brute_force(s: str, words: List[str]) -> List[int]:
    if not words:
        return []
    L, m = len(words[0]), len(words)
    need = Counter(words)
    result = []
    for i in range(len(s) - m * L + 1):
        chunks = Counter(s[j:j + L] for j in range(i, i + m * L, L))
        if chunks == need:
            result.append(i)
    return result

def brute_force(nums: List[int], k: int) -> List[float]:
    result = []
    for i in range(len(nums) - k + 1):
        window = sorted(nums[i:i + k])
        if k % 2:
            result.append(float(window[k // 2]))
        else:
            result.append((window[k // 2 - 1] + window[k // 2]) / 2)
    return result

