def brute_force(ratings: List[int]) -> int:
    n = len(ratings)
    candies = [1] * n
    changed = True
    while changed:                                   # repeat until no rule is violated
        changed = False
        for i in range(n):
            for j in (i - 1, i + 1):
                if 0 <= j < n and ratings[i] > ratings[j] and candies[i] <= candies[j]:
                    candies[i] = candies[j] + 1
                    changed = True
    return sum(candies)

